export type Cell = [number, number];

const NEIGHBORS_REQUIRED_TO_SURVIVE = 2;

export function nextGeneration(livingCells: Cell[]): Cell[] {
  return livingCells.filter(
    (cell) => countLivingNeighbors(cell, livingCells) === NEIGHBORS_REQUIRED_TO_SURVIVE,
  );
}

function countLivingNeighbors(cell: Cell, livingCells: Cell[]): number {
  const [x, y] = cell;
  return livingCells.filter(
    ([otherX, otherY]) =>
      !(otherX === x && otherY === y) &&
      Math.abs(otherX - x) <= 1 &&
      Math.abs(otherY - y) <= 1,
  ).length;
}
EOF
